<iframe id="outsourcingDownloadFrame" name="outsourcingDownloadFrame" title="외주비 파일 다운로드" style="display:none;width:0;height:0;border:0" aria-hidden="true"></iframe>

<script>
(function(){
var form=document.getElementById('outsourcingCostForm'), picker=document.getElementById('outsourcingAttachmentPicker'), list=document.getElementById('outsourcingSelectedFiles'), dropZone=document.getElementById('outsourcingDropZone'), saveBtn=document.getElementById('outsourcingSaveButton'), saveStatus=document.getElementById('outsourcingSaveStatus');
var selected=[], deleteUrl='<?php echo h(base_url()); ?>/?r=construction/outsourcing_file_download&action=delete';
var downloadFrame=document.getElementById('outsourcingDownloadFrame');
document.addEventListener('click',function(e){var a=e.target;while(a&&a!==document&&!((a.className||'').toString().indexOf('js-outsourcing-download')!==-1)){a=a.parentNode;}if(!a||a===document||!downloadFrame)return;e.preventDefault();e.stopPropagation();var href=a.getAttribute('href');if(!href)return;downloadFrame.src='about:blank';setTimeout(function(){downloadFrame.src=href;},0);},false);
function esc(s){var d=document.createElement('div');d.textContent=s||'';return d.innerHTML;}
function keyOf(f){return [f.name,f.size,f.lastModified].join('::');}
function sizeText(n){if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(1)+' MB';}
function render(){list.innerHTML='';for(var i=0;i<selected.length;i++){var x=selected[i], div=document.createElement('div');div.className='rounded-xl border border-gray-200 bg-white px-3 py-2';div.setAttribute('data-file-key',x.key);div.innerHTML='<div class="flex items-center gap-3"><div class="min-w-0 flex-1"><div class="truncate text-sm font-bold text-gray-800">'+esc(x.file.name)+'</div><div class="mt-1 text-xs text-gray-500">'+sizeText(x.file.size)+' · 저장 시 함께 첨부</div></div><button type="button" class="js-selected-remove rounded-full border border-gray-300 px-2 py-1 text-sm font-extrabold text-gray-500" data-key="'+esc(x.key)+'">×</button></div>';list.appendChild(div);}}
function syncPicker(){if(!picker||typeof DataTransfer==='undefined')return false;try{var transfer=new DataTransfer();for(var i=0;i<selected.length;i++)transfer.items.add(selected[i].file);picker.files=transfer.files;return true;}catch(ex){return false;}}
function addFiles(files){if(!files)return false;for(var i=0;i<files.length;i++){var f=files[i],k=keyOf(f),dup=false;for(var j=0;j<selected.length;j++)if(selected[j].key===k)dup=true;if(!dup)selected.push({key:k,file:f});}var synced=syncPicker();render();return synced;}
if(picker) picker.addEventListener('change',function(){var files=[];for(var i=0;i<picker.files.length;i++)files.push(picker.files[i]);addFiles(files);});
if(list) list.addEventListener('click',function(e){var b=e.target;if(!b.classList.contains('js-selected-remove'))return;var k=b.getAttribute('data-key'),next=[];for(var i=0;i<selected.length;i++)if(selected[i].key!==k)next.push(selected[i]);selected=next;syncPicker();render();});
if(dropZone){dropZone.addEventListener('dragenter',function(e){e.preventDefault();dropZone.classList.add('border-blue-500','bg-blue-50');});dropZone.addEventListener('dragover',function(e){e.preventDefault();e.dataTransfer.dropEffect='copy';dropZone.classList.add('border-blue-500','bg-blue-50');});dropZone.addEventListener('dragleave',function(e){if(e.relatedTarget&&dropZone.contains(e.relatedTarget))return;dropZone.classList.remove('border-blue-500','bg-blue-50');});dropZone.addEventListener('drop',function(e){e.preventDefault();dropZone.classList.remove('border-blue-500','bg-blue-50');var previousCount=selected.length;if(!addFiles(e.dataTransfer.files)){selected=selected.slice(0,previousCount);render();alert('이 브라우저에서는 드래그 첨부를 지원하지 않습니다. 파일 추가 버튼을 이용해주세요.');}});}
if(form) form.addEventListener('submit',function(){syncPicker();if(saveBtn)saveBtn.disabled=true;if(saveStatus)saveStatus.textContent=selected.length>0?'외주비 및 첨부파일 저장 중...':'외주비 저장 중...';});
var existing=document.getElementById('outsourcingExistingFiles');if(existing)existing.addEventListener('click',function(e){var b=e.target;if(!b.classList.contains('js-outsourcing-existing-delete'))return;if(!confirm('이 첨부파일을 Google Drive에서도 삭제할까요?'))return;b.disabled=true;var fd=new FormData();fd.append('_csrf',form.elements['_csrf'].value);fd.append('file_id',b.getAttribute('data-file-id'));var xhr=new XMLHttpRequest();xhr.open('POST',deleteUrl,true);xhr.onreadystatechange=function(){if(xhr.readyState!==4)return;var r=null;try{r=JSON.parse(xhr.responseText);}catch(ex){}if(xhr.status>=200&&xhr.status<300&&r&&r.ok){var row=b.closest('[data-existing-file-id]');if(row)row.parentNode.removeChild(row);}else{b.disabled=false;alert(r&&r.message?r.message:'파일 삭제에 실패했습니다.');}};xhr.send(fd);});

var searchInput=document.getElementById('outsourcingVendorSearch'),suggestList=document.getElementById('outsourcingVendorSuggestList'),timer=null,seq=0;if(searchInput&&suggestList){function hide(){suggestList.innerHTML='';suggestList.className+=' hidden';suggestList.style.display='none';}function show(items){suggestList.innerHTML='';for(var i=0;i<items.length;i++){var b=document.createElement('button');b.type='button';b.className='block w-full text-left px-3 py-2 border-b hover:bg-blue-50';b.textContent=items[i].vendor_name||'';b.vendorData=items[i];suggestList.appendChild(b);}suggestList.className=suggestList.className.replace(/\bhidden\b/g,'');suggestList.style.display='block';}searchInput.addEventListener('input',function(){var q=searchInput.value.replace(/^\s+|\s+$/g,'');if(timer)clearTimeout(timer);seq++;var s=seq;if(q.length<2){hide();return;}timer=setTimeout(function(){var x=new XMLHttpRequest();x.open('GET','<?php echo h(base_url()); ?>/?r=construction/material_vendor_search&q='+encodeURIComponent(q),true);x.onreadystatechange=function(){if(x.readyState!==4||s!==seq)return;var items=[];if(x.status===200)try{var r=JSON.parse(x.responseText);items=r&&r.items?r.items:[];}catch(ex){}show(items);};x.send();},250);});suggestList.addEventListener('click',function(e){var b=e.target;if(!b.vendorData)return;var d=b.vendorData;if(form.elements['company_name'])form.elements['company_name'].value=d.vendor_name||'';if(form.elements['representative_name'])form.elements['representative_name'].value=d.representative||'';if(form.elements['business_no'])form.elements['business_no'].value=d.biz_no||'';if(form.elements['contact'])form.elements['contact'].value=d.phone||'';searchInput.value=d.vendor_name||'';hide();});document.addEventListener('click',function(e){if(searchInput.parentNode&&!searchInput.parentNode.contains(e.target))hide();});}
})();
</script>

<div class="mt-4 bg-white rounded-3xl border border-gray-200 p-4 shadow-sm overflow-x-auto"><table class="min-w-[1520px] w-full border border-gray-200 text-sm"><thead class="bg-gray-100 text-gray-700"><tr><th class="border px-3 py-2">일자</th><th class="border px-3 py-2">구분</th><th class="border px-3 py-2">업체명</th><th class="border px-3 py-2">대표자명</th><th class="border px-3 py-2">사업자번호</th><th class="border px-3 py-2">연락처</th><th class="border px-3 py-2 text-right">금액</th><th class="border px-3 py-2">선급여부</th><th class="border px-3 py-2">비고</th><th class="border px-3 py-2">파일</th><th class="border px-3 py-2">관리</th></tr></thead><tbody>
<?php foreach ($manualAllRows as $row): ?><?php $rid=(int)$row['id'];$rdate=(string)$row['expense_date'];$rym=CostChangeService::effectiveSettlementYm($pdo,'outsourcing',(string)$rid,'outsourcing',$rdate);$rlock=CostChangeService::lockInfo('outsourcing',$rdate,$rym,date('Y-m-d'));$active=$rid>0?CostChangeService::activeRequest($pdo,'outsourcing',(string)$rid):null;$history=$rid>0?CostChangeService::historyCount($pdo,'outsourcing',(string)$rid):0;$latest=$history>0?CostChangeService::latestRequest($pdo,'outsourcing',(string)$rid):null;$returnUrl='?r=공사&pid='.(int)$pid.'&tab=outsourcing&outsourcing_tab=input&month='.$selectedMonth; ?><tr class="<?php echo !empty($rlock['locked'])?'bg-gray-50':''; ?>"><td class="border px-3 py-2"><?php echo h($row['expense_date']); ?></td><td class="border px-3 py-2">외주비</td><td class="border px-3 py-2 font-bold"><?php echo h($row['company_name']); ?></td><td class="border px-3 py-2"><?php echo h(isset($row['representative_name'])?$row['representative_name']:''); ?></td><td class="border px-3 py-2"><?php echo h(isset($row['business_no'])?$row['business_no']:''); ?></td><td class="border px-3 py-2"><?php echo h(isset($row['contact'])?$row['contact']:''); ?></td><td class="border px-3 py-2 text-right font-bold"><?php echo h(number_format((float)$row['amount'])); ?></td><td class="border px-3 py-2 text-center font-extrabold"><?php echo isset($row['advance_payment_yn'])&&(string)$row['advance_payment_yn']==='Y'?'Y':'N'; ?></td><td class="border px-3 py-2"><?php echo h(isset($row['memo'])&&trim((string)$row['memo'])!==''?$row['memo']:'-'); ?></td><td class="border px-3 py-2"><?php $files=isset($outsourcingFilesByCost[$rid])?$outsourcingFilesByCost[$rid]:array(); if(count($files)===0): ?><span class="text-gray-400">-</span><?php else: ?><div class="flex flex-col gap-1"><?php foreach($files as $f): ?><div class="flex items-center gap-2"><a target="_blank" rel="noopener" class="text-xs font-bold text-blue-700 hover:underline" href="<?php echo h(base_url()); ?>/?r=construction/outsourcing_file_download&id=<?php echo (int)$f['id']; ?>"><?php echo h($f['original_name']); ?></a><a class="js-outsourcing-download text-[11px] text-gray-500 underline" target="outsourcingDownloadFrame" href="<?php echo h(base_url()); ?>/?r=construction/outsourcing_file_download&id=<?php echo (int)$f['id']; ?>&download=1">다운</a></div><?php endforeach; ?></div><?php endif; ?></td><td class="border px-3 py-2"><?php if(is_array($active)): ?><div class="text-center text-xs font-extrabold text-amber-700"><?php echo h(CostChangeService::statusLabel($active['status'])); ?></div><?php elseif(!empty($rlock['locked'])): ?><div class="flex flex-wrap justify-center gap-1"><?php foreach(array('MODIFY'=>'수정 승인 요청','MONTH_MOVE'=>'귀속월 변경 요청','DELETE'=>'삭제 승인 요청') as $code=>$label): ?><a href="?r=cost_change/request&project_id=<?php echo (int)$pid; ?>&target_type=outsourcing&target_id=<?php echo $rid; ?>&request_type=<?php echo h($code); ?>&return_url=<?php echo rawurlencode($returnUrl); ?>" class="px-2 py-1 rounded-lg border border-amber-200 bg-amber-50 text-amber-800 text-[11px] font-bold"><?php echo h($label); ?></a><?php endforeach; ?></div><?php else: ?><div class="flex justify-center gap-2"><a href="?r=공사&pid=<?php echo (int)$pid; ?>&tab=outsourcing&outsourcing_tab=input&month=<?php echo h($rym); ?>&edit_id=<?php echo $rid; ?>" class="px-2 py-1 rounded-lg border border-gray-300 text-xs font-bold">수정</a><form method="post" action="<?php echo h(base_url()); ?>/?r=construction/outsourcing_cost_save" onsubmit="return confirm('이 외주비 입력 내역을 삭제할까요?');"><input type="hidden" name="_csrf" value="<?php echo h(csrf_token()); ?>"><input type="hidden" name="project_id" value="<?php echo (int)$pid; ?>"><input type="hidden" name="month" value="<?php echo h($rym); ?>"><input type="hidden" name="entry_id" value="<?php echo $rid; ?>"><button name="action" value="delete" class="px-2 py-1 rounded-lg border border-red-200 text-red-600 text-xs font-bold">삭제</button></form></div><?php endif; ?><?php if($history>0): ?><div class="mt-1 text-center"><a href="?r=cost_change/history&target_type=outsourcing&target_id=<?php echo $rid; ?>&project_id=<?php echo (int)$pid; ?>" class="text-[11px] font-bold text-blue-700 underline"><?php echo h(CostChangeService::historyBadgeLabel($latest,$history)); ?></a></div><?php endif; ?></td></tr><?php endforeach; ?>
<?php if(count($manualAllRows)===0): ?><tr><td colspan="11" class="border px-3 py-8 text-center text-gray-500">입력된 외주비가 없습니다.</td></tr><?php endif; ?></tbody></table></div>
<?php endif; ?>
